[ "$actual_checkpoint_sha" = "3cc349b35275752194874d6aa1db1e5b937874f9c7ef4dcca2f35d6c0e602a2c" ] || { echo "FAIL_REVIEWED_CTS_IDENTITY"; exit 12; }
